command:
cd /app && python3 - <<'PYEOF'
p='crates/wasmi/tests/coredump_details.rs'
s=open(p).read()
old = """    let globals = global_section.expect("global section");
    assert_eq!(globals.len(), 2);
    assert_eq!(
        globals[0].ty,
        GlobalType { content_type: wasmparser::ValType::I32, mutable: false, shared: false }
    );
    assert_eq!(
        globals[1].ty,
        GlobalType { content_type: wasmparser::ValType::F64, mutable: true, shared: false }
    );
"""
new = """    let globals = global_section.expect("global section");
    assert_eq!(globals.len(), 2);
    assert_eq!(
        globals[0].ty,
        GlobalType { content_type: wasmparser::ValType::I32, mutable: false, shared: false }
    );
    assert_eq!(
        globals[1].ty,
        GlobalType { content_type: wasmparser::ValType::F64, mutable: true, shared: false }
    );
    // Verify the current values of the globals at trap time.
    let mut ops = globals[0].init_expr.get_operators_reader();
    match ops.read().unwrap() {
        wasmparser::Operator::I32Const { value } => assert_eq!(value, 7),
        _ => panic!("expected i32.const 7"),
    }
    let mut ops = globals[1].init_expr.get_operators_reader();
    match ops.read().unwrap() {
        wasmparser::Operator::F64Const { value } => assert_eq!(value, 2.5),
        _ => panic!("expected f64.const 2.5"),
    }
"""
assert old in s
s=s.replace(old, new)
open(p,'w').write(s)
PYEOF
cd /app && cargo test -p wasmi --test coredump_details 2>&1 | tail -30
